                                         d->scatter_dst[i]);
                all_passed = false;
            }
        }
        std::fill(d->scatter_dst.begin(), d->scatter_dst.end(), 0);
        if (!all_passed) {
            report_fail_msg("sve512_gather_scatter_svd: SDC detected");
            return EXIT_FAILURE;
        }
    } while (test_time_condition(test));
