                for (size_t lane = 0; lane < d->vl_d; ++lane) {
                    if (!f64_lane_ok(golds64[lane], hw[lane])) {
                        report_f64_lane_mismatch(
                            "sve512_f64_special_svd", lane,
                            golds64[lane], hw[lane]);
                        all_passed = false;
                    }
                }
            }
        }
        if (!all_passed) {
