    } while (test_time_condition(test));
    return EXIT_SUCCESS;
}

static int sve512_f64_special_svd_cleanup(struct test *test)
{
    delete static_cast<SveF64SpecialSvdData *>(test->data);
    return EXIT_SUCCESS;
}

#endif // __aarch64__

DECLARE_TEST(sve512_f64_special_svd,
