// Host-side simulation of sve512_gather_scatter_svd's fixed init permutation.
// Pure integer logic (no SVE) — runs anywhere. Verifies:
//   1. every flat index touched stays < ROWS*COLS (no OOB)
//   2. the resulting gather_idx is still a full permutation of 0..N-1
//   3. golden precompute visits every index (permutation => full coverage)
#include <cstdio>
#include <cstdint>
#include <vector>

static const size_t SVD_ROWS = 300, SVD_COLS = 300;
static const size_t SVD_BLOCK_ROWS = 16, SVD_BLOCK_COLS = 16;

static inline uint64_t splitmix64(uint64_t x)
{
    uint64_t z = (x + 0x9E3779B97F4A7C15ULL);
    z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ULL;
    z = (z ^ (z >> 27)) * 0x94D049BB133111EBULL;
    return z ^ (z >> 31);
}

int main()
{
    const size_t gn = SVD_ROWS * SVD_COLS;
    std::vector<uint64_t> idx(gn);
    for (size_t i = 0; i < gn; ++i) idx[i] = i;

    size_t max_flat = 0, swaps = 0;
    for (size_t br = 0; br < SVD_ROWS; br += SVD_BLOCK_ROWS) {
        for (size_t bc = 0; bc < SVD_COLS; bc += SVD_BLOCK_COLS) {
            const size_t rows_in = (SVD_ROWS - br < SVD_BLOCK_ROWS) ? (SVD_ROWS - br) : SVD_BLOCK_ROWS;
            const size_t cols_in = (SVD_COLS - bc < SVD_BLOCK_COLS) ? (SVD_COLS - bc) : SVD_BLOCK_COLS;
            for (size_t k = 0; k < rows_in * cols_in; ++k) {
                size_t j = (size_t)(splitmix64(0xBEEF0000ULL + (br * SVD_COLS + bc) * 256 + k) % (k + 1));
                size_t row_i = br + k / cols_in, col_i = bc + k % cols_in;
                size_t row_j = br + j / cols_in, col_j = bc + j % cols_in;
                size_t fi = row_i * SVD_COLS + col_i, fj = row_j * SVD_COLS + col_j;
                if (fi >= gn || fj >= gn) { printf("OOB fi=%zu fj=%zu\n", fi, fj); return 1; }
                if (fi > max_flat) max_flat = fi;
                if (fj > max_flat) max_flat = fj;
                uint64_t t = idx[fi]; idx[fi] = idx[fj]; idx[fj] = t;
                ++swaps;
            }
        }
    }

    // Full permutation check (golden coverage follows from this).
    std::vector<bool> seen(gn, false);
    bool perm = true;
    for (size_t i = 0; i < gn; ++i) {
        if (idx[i] >= gn || seen[idx[i]]) { perm = false; break; }
        seen[idx[i]] = true;
    }

    printf("max_flat=%zu (limit %zu) swaps=%zu permutation=%s\n",
           max_flat, gn - 1, swaps, perm ? "YES" : "NO");
    return (max_flat < gn && perm) ? 0 : 1;
}

