// Host-side simulation of the block-major slab layout used by the three
// fixed chain/special SVD tests. Verifies for every traversed block
// origin (br, bc) and both CHAIN_STEPS variants:
//   max(base + (STEPS-1)*lanes + lanes-1) < total
// for a range of runtime VLs, and prints the actual total sizes.
#include <cstdio>

static const size_t SVD_ROWS = 300, SVD_COLS = 300;
static const size_t SVD_BLOCK_ROWS = 16, SVD_BLOCK_COLS = 16;

int main()
{
    const size_t nbr = (SVD_ROWS + SVD_BLOCK_ROWS - 1) / SVD_BLOCK_ROWS;
    const size_t nbc = (SVD_COLS + SVD_BLOCK_COLS - 1) / SVD_BLOCK_COLS;
    int rc = 0;

    for (unsigned vl : {2u, 4u, 8u, 16u, 32u}) {  // svcntd()/svcntw() lane counts
        for (unsigned steps : {512u, 64u}) {
            const size_t slab = steps * vl;
            const size_t total = nbr * nbc * slab;
            size_t max_idx = 0;
            for (size_t br = 0; br < SVD_ROWS; br += SVD_BLOCK_ROWS)
                for (size_t bc = 0; bc < SVD_COLS; bc += SVD_BLOCK_COLS) {
                    size_t base = ((br / SVD_BLOCK_ROWS) * nbc + (bc / SVD_BLOCK_COLS)) * slab;
                    size_t last = base + (steps - 1) * vl + (vl - 1);
                    if (last > max_idx) max_idx = last;
                }
            const bool ok = max_idx < total;
            if (!ok) rc = 1;
            printf("vl=%2u steps=%3u blocks=%zux%zu total=%9zu max_idx=%9zu %s\n",
                   vl, steps, nbr, nbc, total, max_idx, ok ? "OK" : "OOB!");
        }
    }
    // Actual byte sizes at VL=64B (8 f64 lanes / 16 f32 lanes, 0xd22):
    printf("f64_chain_svd: 2 streams x %zu B = %.1f MB\n",
           361u * 512u * 8u * 8u, 2.0 * 361 * 512 * 8 * 8 / 1048576.0);
    printf("f32_chain_svd: 2 streams x %zu B = %.1f MB\n",
           361u * 512u * 16u * 4u, 2.0 * 361 * 512 * 16 * 4 / 1048576.0);
    printf("f64_special_svd: 2 streams x %zu B = %.2f MB\n",
           361u * 64u * 8u * 8u, 2.0 * 361 * 64 * 8 * 8 / 1048576.0);
    return rc;
}

