// Host-side scalar emulation of example.cpp's kernel (no SVE needed).
// Emulates the 16 lanes exactly as the SVE vectors would compute them,
// to independently determine the per-call per-lane increment.
#include <cstdio>
#include <cstring>
#include <cmath>

int main()
{
    const size_t RADIUS = 6, B_TILE = 16;
    const size_t coord = 10, extent = 56, stride = 64;
    const size_t ITERS = 10;   // increment is iteration-independent; 10 suffices

    // Layout: [extent][stride][B_TILE], src[i] = i%16+1
    static double src[56 * 64 * 16];
    for (size_t i = 0; i < sizeof(src) / sizeof(src[0]); ++i)
        src[i] = (double)(i % B_TILE + 1);

    double coeff[RADIUS + 1] = {};
    for (size_t r = 1; r <= RADIUS; ++r) coeff[r] = 0.125;

    const size_t base = coord * stride * B_TILE;   // = 10240
    double res[B_TILE] = {};

    for (size_t it = 0; it < ITERS; ++it) {
        for (size_t r = 1; r <= RADIUS; ++r) {
            const ptrdiff_t off = (ptrdiff_t)(r * stride) * B_TILE;
            int dir_taken = 0;
            if (coord >= r) {            // negative direction
                for (size_t l = 0; l < B_TILE; ++l)
                    res[l] = std::fma(coeff[r], src[base - off + l], res[l]);
                ++dir_taken;
            }
            if (coord + r < extent) {    // positive direction
                for (size_t l = 0; l < B_TILE; ++l)
                    res[l] = std::fma(coeff[r], src[base + off + l], res[l]);
                ++dir_taken;
            }
            if (r == 1)
                printf("r=%zu: directions executed = %d (coord>=r: %s, coord+r<extent: %s)\n",
                       r, dir_taken, coord >= r ? "yes" : "no",
                       coord + r < extent ? "yes" : "no");
        }
    }

    printf("\nlane | after %zu iters | per-call increment | code's expected/call\n", ITERS);
    for (size_t l = 0; l < B_TILE; ++l)
        printf("%4zu | %14.1f | %18.3f | %17.1f\n",
               l, res[l], res[l] / ITERS, 1.0 * (l + 1));

    printf("\nper-call increment / (j+1) for each lane:\n");
    for (size_t l = 0; l < B_TILE; ++l)
        printf("lane %2zu: %.6f\n", l, (res[l] / ITERS) / (l + 1));
    return 0;
}
